#include <vector>

class Solution {
public:
    int minOperationsToZeroXOR(std::vector<int>& nums) {
        int xor_sum = 0;
        for (int x : nums) xor_sum ^= x;
        return xor_sum == 0 ? 0 : 1;
    }
};

